export function HumanApproval({
  request = "{{request}}",
  status = "{{status}}",
  accent = "{{accent}}",
  requireReason = {{requireReason}},
}) {
  const statusStyle = {
    pending: { background: "#24143012", color: "#241430", dot: accent },
    approved: { background: "#A8E6C140", color: "#1c5c3a", dot: "#2f8f5b" },
    rejected: { background: "#F5C2E040", color: "#7a1f4a", dot: "#c23b6f" },
  }[status] ?? { background: "#24143012", color: "#241430", dot: accent };
  return (
    <div style={{ maxWidth: 420, padding: "16px 18px", borderRadius: 12, background: "#FAF7F2", color: "#241430", border: "1px solid #24143020", boxSizing: "border-box", font: "15px/1.5 system-ui, sans-serif" }}>
      <p style={{ margin: "0 0 12px" }}>{request}</p>
      <div style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 12, fontWeight: 700, textTransform: "capitalize", padding: "4px 10px", borderRadius: 999, marginBottom: 12, background: statusStyle.background, color: statusStyle.color }}>
        <span aria-hidden="true" style={{ width: 7, height: 7, borderRadius: "50%", background: statusStyle.dot }} />
        {status}
      </div>
      {requireReason && (
        <div style={{ display: "flex", flexDirection: "column", gap: 4, marginBottom: 14, fontSize: 13 }}>
          <label htmlFor="human-approval-react-reason">Reason (required before deciding)</label>
          <textarea id="human-approval-react-reason" rows={2} placeholder="Why are you approving or rejecting this?" style={{ font: "inherit", padding: 8, borderRadius: 8, border: "1px solid #24143030", resize: "vertical", background: "#fff", color: "#241430" }} />
        </div>
      )}
      <div style={{ display: "flex", gap: 10 }}>
        <button type="button" style={{ font: "600 14px system-ui, sans-serif", padding: "8px 16px", borderRadius: 8, cursor: "pointer", border: "1.5px solid transparent", background: accent, color: "#241430" }}>Approve</button>
        <button type="button" style={{ font: "600 14px system-ui, sans-serif", padding: "8px 16px", borderRadius: 8, cursor: "pointer", background: "transparent", border: "1.5px solid #24143040", color: "#241430" }}>Reject</button>
      </div>
    </div>
  );
}
